"""Module 08 concepts: voltage regulators (Floyd 9e Ch.17)."""
from lib import K
M = 'm08'
K('m08-regulation', M, ('Điều chỉnh đường dây và tải', 'Line and load regulation'),
  ('Line regulation đo ΔVOUT khi điện áp vào đổi; load regulation đo ΔVOUT khi dòng tải đổi. Bộ ổn áp tốt có cả hai gần 0.', 'Line regulation measures ΔVOUT when the input voltage changes; load regulation measures ΔVOUT when the load current changes. A good regulator keeps both near zero.'),
  facts=[('Line = (ΔVOUT/ΔVIN)·100 %', ('Cũng viết theo %/V.', 'Also quoted in %/V.')), ('Load = (VNL − VFL)/VFL·100 %', ('VNL: không tải; VFL: đầy tải.', 'VNL: no load; VFL: full load.'))],
  steps=[('Xác định đại lượng nào đổi (VIN hay IL).', 'Identify which quantity changes (VIN or IL).'), ('Mẫu số của load regulation là VFL, không phải VNL.', 'The load-regulation denominator is VFL, not VNL.')],
  traps=[('Nhầm line với load regulation.', 'Mixing line and load regulation.'), ('Dùng VNL ở mẫu số.', 'Using VNL in the denominator.')],
  angles=[('VNL = 5,05 V, VFL = 5,00 V: load regulation?', 'VNL = 5.05 V, VFL = 5.00 V: load regulation?'), ('ΔVOUT = 2 mV khi VIN đổi 6 V: line regulation?', 'ΔVOUT = 2 mV for a 6 V change in VIN: line regulation?')],
  topics=['Regulation and regulator blocks'], kw=['line regulation', 'load regulation', 'regulation', 'no-load', 'full-load', 'percent', 'regulator', 'voltage regulator'], kwv=['điều chỉnh đường dây', 'điều chỉnh tải', 'line regulation', 'load regulation', 'ổn áp', 'không tải', 'đầy tải'],
  src=['Floyd 9e §17–1'], related=['m08-series'], chk='regulation')
K('m08-series', M, ('Ổn áp tuyến tính nối tiếp', 'Linear series regulator'),
  ('Op-amp so điện áp lấy mẫu với VREF và lái transistor pass sao cho hai điện áp bằng nhau; điện áp ra được đặt bởi bộ chia.', 'An op-amp compares the sampled voltage with VREF and drives the pass transistor so they match; the output voltage is set by the divider.'),
  facts=[('VOUT = (1 + R2/R3)·VREF', ('Mạch không đảo với tham chiếu.', 'A noninverting amplifier of the reference.'))],
  steps=[('Xác định VREF (zener) và tỉ số bộ chia.', 'Find VREF (zener) and the divider ratio.'), ('Thế vào công thức không đảo.', 'Substitute into the noninverting formula.')],
  traps=[('Quên “1 +”.', 'Forgetting the “1 +”.')],
  angles=[('VREF = 2,4 V, R2 = 5,6 kΩ, R3 = 2,2 kΩ: VOUT?', 'VREF = 2.4 V, R2 = 5.6 kΩ, R3 = 2.2 kΩ: VOUT?')],
  topics=['Series regulators and current limiting', 'Regulation and regulator blocks'], kw=['series regulator', 'pass transistor', 'error amplifier', 'reference', 'zener', 'sampling', 'linear regulator'], kwv=['ổn áp nối tiếp', 'transistor pass', 'bộ khuếch đại sai số', 'điện áp tham chiếu', 'zener', 'ổn áp tuyến tính'],
  src=['Floyd 9e §17–2'], related=['m08-regulation', 'm08-current-limit', 'm02-noninverting'], chk='series')
K('m08-current-limit', M, ('Giới hạn dòng', 'Current limiting'),
  ('Một điện trở nhỏ R4 mắc nối tiếp với tải; khi sụt áp tới 0,7 V một transistor bảo vệ dẫn và kìm dòng tải ở mức IL(max).', 'A small resistor R4 in series with the load; when its drop reaches 0.7 V a protection transistor conducts and holds the load current at IL(max).'),
  facts=[('IL(max) = 0,7 V/R4', ('R4 = 0,7/IL(max).', 'R4 = 0.7/IL(max).')), ('P_R4 = IL(max)²·R4', ('Công suất tiêu tán trên R4.', 'Power dissipated in R4.')), ('Rext = 0,7 V/IREG(max)', ('Transistor pass ngoài.', 'External pass transistor.'))],
  steps=[('Chọn dòng giới hạn → R4 = 0,7/IL(max).', 'Pick the limit current → R4 = 0.7/IL(max).'), ('Kiểm công suất R4 = I²R.', 'Check the R4 power = I²R.')],
  traps=[('Giảm R4 làm dòng giới hạn TĂNG, không giảm.', 'Lowering R4 RAISES the limit current.')],
  angles=[('IL(max) = 250 mA: chọn R4 và công suất.', 'IL(max) = 250 mA: choose R4 and its power.'), ('Giảm một nửa R4 thì dòng giới hạn?', 'If R4 is halved, what is the limit current?')],
  topics=['Series regulators and current limiting'], kw=['current limiting', 'current limit', 'short circuit', 'overload', 'foldback', 'r4', '0.7 v', 'protection'], kwv=['giới hạn dòng', 'ngắn mạch', 'quá tải', 'bảo vệ', 'foldback'],
  src=['Floyd 9e §17–2, 17–4'], related=['m08-series'], chk='currentlimit')
K('m08-shunt', M, ('Ổn áp song song', 'Shunt regulator'),
  ('Transistor mắc song song với tải hút phần dòng thừa qua điện trở nối tiếp R1; dòng ngắn mạch được R1 giới hạn nên hiệu suất thấp nhưng an toàn.', 'A transistor in parallel with the load shunts the excess current through the series resistor R1; R1 limits the short-circuit current, so efficiency is lower but the circuit is safe.'),
  facts=[('IL(max) = VIN/R1 (ngắn mạch)', ('Dòng ngắn mạch bị R1 giới hạn.', 'R1 limits the short-circuit current.')), ('P_R1 = IR1²·R1', ('Công suất tiêu tán trên R1.', 'Power dissipated in R1.'))],
  steps=[('Dòng qua R1 = (VIN − VOUT)/R1; chia giữa tải và transistor.', 'The current in R1 = (VIN − VOUT)/R1, shared by the load and the transistor.')],
  traps=[('Nghĩ ổn áp song song hiệu suất cao: nó thua loại nối tiếp.', 'Thinking a shunt regulator is efficient: it is worse than the series type.')],
  angles=[('ΔIC khi tải đổi: 1 V/100 Ω = 10 mA.', 'ΔIC when the load changes: 1 V/100 Ω = 10 mA.'), ('Dòng ngắn mạch cực đại.', 'The maximum short-circuit current.')],
  topics=['Shunt regulators'], kw=['shunt regulator', 'shunt', 'parallel', 'short circuit', 'r1', 'excess current'], kwv=['ổn áp song song', 'song song', 'ngắn mạch', 'dòng thừa'],
  src=['Floyd 9e §17–3'], related=['m08-series'], chk='shunt')
K('m08-ic-regulators', M, ('IC ổn áp 78XX/79XX và LM317', 'IC regulators 78XX/79XX and the LM317'),
  ('78XX cố định dương, 79XX cố định âm; LM317 điều chỉnh được nhờ hai điện trở. VIN phải lớn hơn VOUT một điện áp dropout (≈ 2 V cho 78XX, ≈ 1,5–2 V cho LM317).', '78XX is fixed positive, 79XX fixed negative; the LM317 is adjustable with two resistors. VIN must exceed VOUT by the dropout voltage (≈ 2 V for 78XX, ≈ 1.5–2 V for the LM317).'),
  facts=[('LM317: VOUT = 1,25 V·(1 + R2/R1) + IADJ·R2', ('IADJ nhỏ nên thường bỏ qua.', 'IADJ is small and is often neglected.')), ('Rext = 0,7 V/IREG(max)', ('Mở rộng dòng bằng transistor pass ngoài.', 'Extend the current with an external pass transistor.'))],
  steps=[('Chọn R1 theo datasheet rồi giải R2.', 'Pick R1 from the datasheet and solve for R2.'), ('Kiểm VIN ≥ VOUT + dropout.', 'Check VIN ≥ VOUT + dropout.')],
  traps=[('Quên cộng IADJ·R2 khi đề cho IADJ.', 'Forgetting IADJ·R2 when IADJ is given.'), ('Nhầm 7805 (dương) với 7905 (âm).', 'Confusing the 7805 (positive) with the 7905 (negative).')],
  angles=[('Chọn R2 để LM317 ra 9 V.', 'Choose R2 for 9 V from an LM317.'), ('Điện áp vào tối thiểu cho 78XX ra 12 V.', 'Minimum input for a 78XX giving 12 V.')],
  topics=['IC regulators'], kw=['lm317', '7805', '78xx', '79xx', 'adjustable regulator', 'fixed regulator', 'dropout', 'three-terminal', 'iadj', 'ic regulator'], kwv=['lm317', '7805', '78xx', '79xx', 'ổn áp điều chỉnh', 'ổn áp cố định', 'dropout', 'ic ổn áp'],
  src=['Floyd 9e §17–4'], related=['m08-series', 'm08-heat'], chk='lm317')
K('m08-switching', M, ('Ổn áp xung', 'Switching regulators'),
  ('Transistor đóng/ngắt nhanh với chu kỳ làm việc duty = ton/T; điện áp ra trung bình tỉ lệ với duty nên hiệu suất cao hơn bộ tuyến tính. Có ba kiểu: giảm áp, tăng áp, đảo cực.', 'A transistor switches rapidly with duty = ton/T; the average output follows the duty cycle, so efficiency is higher than a linear regulator. Three types: step-down, step-up and inverting.'),
  facts=[('Giảm áp: VOUT ≈ duty × VIN ,  duty = ton/T', ('Ví dụ T = 100 μs, ton = 40 μs → 40 %.', 'For example T = 100 μs, ton = 40 μs → 40 %.')), ('η = POUT/PIN', ('Bộ tuyến tính: η ≈ VOUT/VIN.', 'Linear regulator: η ≈ VOUT/VIN.'))],
  steps=[('duty = ton/T rồi VOUT = duty × VIN (giảm áp).', 'duty = ton/T then VOUT = duty × VIN (step-down).'), ('Hiệu suất = công suất ra/công suất vào.', 'Efficiency = output power/input power.')],
  traps=[('Dùng công thức giảm áp cho bộ tăng áp.', 'Using the step-down formula for a step-up.')],
  angles=[('VIN = 24 V, duty = 25 %: VOUT?', 'VIN = 24 V, duty = 25 %: VOUT?'), ('So hiệu suất xung với tuyến tính.', 'Compare switching and linear efficiency.')],
  topics=['Switching regulators'], kw=['switching regulator', 'switching', 'duty cycle', 'step-down', 'step-up', 'buck', 'boost', 'inverting regulator', 'ton'], kwv=['ổn áp xung', 'chu kỳ làm việc', 'giảm áp', 'tăng áp', 'đảo cực', 'buck', 'boost'],
  src=['Floyd 9e §17–5'], related=['m08-ic-regulators', 'm07-555-astable'], chk='switching')
K('m08-heat', M, ('Công suất tiêu tán và hiệu suất của ổn áp tuyến tính', 'Dissipation and efficiency of a linear regulator'),
  ('Bộ ổn áp tuyến tính tiêu tán (VIN − VOUT)·IL dưới dạng nhiệt nên hiệu suất ≈ VOUT/VIN; VIN cao hơn cần thiết thì lãng phí và nóng.', 'A linear regulator dissipates (VIN − VOUT)·IL as heat, so efficiency ≈ VOUT/VIN; a VIN higher than needed wastes power and runs hot.'),
  facts=[('P_D = (VIN − VOUT)·IL', ('Công suất tiêu tán trên phần tử pass.', 'Power dissipated in the pass element.')), ('η ≈ VOUT/VIN', ('Bỏ qua dòng tĩnh.', 'Quiescent current neglected.'))],
  steps=[('Tính P_D rồi chọn tản nhiệt hoặc giảm VIN.', 'Compute P_D, then pick a heat sink or lower VIN.')],
  traps=[('Dùng tổng VIN·IL làm công suất tiêu tán.', 'Using VIN·IL as the dissipated power.')],
  angles=[('VIN = 12 V, VOUT = 5 V, IL = 0,5 A: P_D và hiệu suất?', 'VIN = 12 V, VOUT = 5 V, IL = 0.5 A: P_D and efficiency?')],
  topics=['IC regulators', 'Series regulators and current limiting'], kw=['power dissipation', 'heat sink', 'efficiency', 'thermal', 'dissipate', 'junction temperature'], kwv=['công suất tiêu tán', 'tản nhiệt', 'hiệu suất', 'nhiệt'],
  src=['Floyd 9e §17–4'], related=['m08-ic-regulators', 'm08-switching'], chk='heat')
